  if (!candidates.length) throw Error('Cached browser driver unavailable');
  const { chromium } = require(candidates[0]);
  const browser = await chromium.connectOverCDP('http://127.0.0.1:' + port);
  const page = browser.contexts().flatMap(context => context.pages()).find(item => item.url().includes('/__/#/specs'));
  if (!page) throw Error('Actual Cypress runner unavailable');
  await page.bringToFront();
  run.windowProof('runner-connected');
  if (!await page.evaluate(() => document.visibilityState === 'visible')) throw Error('Runner not visible');
  run.write('runner-connected.json', { at: new Date().toISOString(), applicationOpened: true, specLoaded: false, testsCompleted: false });
  run.sourceCheck('before-spec');
  if (new URL(page.url()).hash !== '#/specs') await page.locator('a[href="#/specs"]').first().click();
  await page.locator('a[href="#/specs/runner?file=' + run.spec + '"]').click();
  await page.waitForFunction(spec => window.Cypress?.spec?.relative.replaceAll('\\', '/') === spec, run.spec);
  run.write('spec-loaded.json', { at: new Date().toISOString(), spec: run.spec, specLoaded: true, testsCompleted: false });
